#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""MyDesk v301 適用（見積を店舗ベースに強化：店舗×品目表・一括単価・Googleマップ・業者情報表示・通話メモ書き戻し・全リンク最新化・自動ステータス）
使い方: dashboard.jsx と同じフォルダで  python3 apply_v301_dashboard.py"""
import gzip, base64, json, sys, os
PATH="dashboard.jsx"
if not os.path.exists(PATH):
    print("❌ dashboard.jsx が見つかりません。同じフォルダで実行してください。"); sys.exit(1)
PAIRS=json.loads('[["H4sIAHYAa2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zUy1i0zNjDQLSzNL0nVLcgvKknM0c3LLyhKTcvJTM8oUbJW0NdXeNw8+XHz6sfNnS/WznjasfTp2gkA9YjFo1YAAAA=", "H4sIAHYAa2oC/0vOzysuUfCNdHEN9o53CvX0cVGwVVAyMjAy0zUw1zUy0S0zNjDULSzNL0nVLS7JL0rVLSjKTM7MS1eyVtDXV3jcPPlx8+rHzZ0v1s542rH06doJAGJ3xCpRAAAA"], ["", ""]]')
def dec(b): return gzip.decompress(base64.b64decode(b)).decode("utf-8")
raw=open(PATH,"rb").read(); had_crlf=b"\r\n" in raw
text=raw.replace(b"\r\n",b"\n").decode("utf-8")
applied=skipped=0
for eo,en in PAIRS:
    old,new=dec(eo),dec(en)
    if text.count(new)>=1: skipped+=1; continue
    c=text.count(old)
    if c==0:
        print("❌ 対象が見つかりません（現在のビルドを確認）:"); print("   "+old[:80].replace("\n"," / ")); print("   grep MYDESK_BUILD dashboard.jsx"); sys.exit(1)
    if c!=1:
        print("❌ 対象が%d箇所（1箇所想定）"%c); sys.exit(1)
    text=text.replace(old,new,1); applied+=1
out=text.replace("\n","\r\n").encode("utf-8") if had_crlf else text.encode("utf-8")
open(PATH,"wb").write(out)
print("✅ v301 適用完了 (適用 %d / スキップ %d)"%(applied,skipped))
print("   ビルド: 2026-07-24-v301-quote-store-pricing")
